package com.example.apt;

import lombok.Getter;

/**
 * Immutable value type whose getters are generated by Lombok.
 *
 * <p>The class compiles only when Forge runs the annotation processor declared
 * by the Lombok jar on the compile classpath (AGENT.md section 23); without
 * annotation processing, {@code getName()} and {@code getAge()} would not
 * exist.</p>
 */
@Getter
public final class Person {

    private final String name;
    private final int age;

    public Person(String name, int age) {
        this.name = name;
        this.age = age;
    }
}
